import sys
from collections import deque

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, val):
        self.data = val
        self.left = None
        self.right = None

def build_tree(nodes):
    if not nodes:
        return None
    root = Node(nodes[0])
    queue = deque([root])
    i = 1
    while queue and i < len(nodes):
        current = queue.popleft()
        if i < len(nodes) and nodes[i] is not None:
            current.left = Node(nodes[i])
            queue.append(current.left)
        i += 1
        if i < len(nodes) and nodes[i] is not None":
            current.right = Node(nodes[i])
            queue.append(current.right)
        i += 1
    return root

def singlevalued(root):
    count = 0

    def helper(node):
        nonlocal count
        if node is None:
            return True

        left_single = helper(node.left)
        right_single = helper(node.right)

        if left_single and right_single:
            if node.left and node.left.data != node.data:
                return False
            if node.right and node.right.data != node.data:
                return False
            count += 1
            return True
        return False

    helper(root)
    return count

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    if n == 0:
        print(0)
        return

    nodes = []
    for i in range(1, n + 1):
        if i < len(input_data):
            val = input_data[i]
            if val == 'None':
                nodes.append(None)
            else:
                nodes.append(int(val))

    root = build_tree(nodes)
    result = singlevalued(root)
    print(result)

if __name__ == "__main__":
    main()
